export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note with a title and body.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          body: { type: 'string' },
        },
        required: ['title', 'body'],
        additionalProperties: false,
      },
    },
